# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
-- A person's grade is dated: a person may have several grades, each in force from its from-date until
-- the next one's. The first grade a person was given has no from-date: it applies from the beginning of
-- time. A person has at most one grade per from-date (and at most one with none).
CREATE TABLE person_grade (
    person_id BIGINT     NOT NULL REFERENCES person (id),
    from_date DATE,
    grade     VARCHAR(1) NOT NULL
);
CREATE INDEX person_grade_person ON person_grade (person_id);
INSERT INTO person_grade (person_id, from_date, grade) SELECT id, NULL, grade FROM person;
ALTER TABLE person DROP COLUMN grade;
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { PersonView } from './people';

/** DRAFT when added, then OPEN, then SETTLED; a DRAFT, OPEN or PENDING claim can be VOID. A clerk settling a
 *  claim above the clerk limit makes it PENDING, which a steward approves (SETTLED) or rejects (OPEN again). */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

export interface ClaimView {
  id: number;
  personId: number;
  /** The amount with exactly two decimals, e.g. "10.50". */
  amount: string;
  /** yyyy-mm-dd */
  date: string;
  note: string;
  status: ClaimStatus;
  /** The claim's number on its sheet, given when opened: sheet-wide ("1", "2", ...) or within its period
   *  ("P1-1", or "X-1" in no period) while the sheet numbers per period; null while a draft. */
  number: string | null;
  /** The due fixed when the claim was settled, with exactly two decimals; null while it is not
   *  settled, or if its grade had no rate then (its due then follows the rate as an open one does). */
  settledDue: string | null;
  /** The signed-in name of the user who opened the claim; null while a draft. */
  openedBy: string | null;
  /** Whether its person's last statement binds the claim, to `statedDue`. */
  stated: boolean;
  /** The figure the claim had at its person's last statement, while bound by it, with exactly two
   *  decimals; null when not bound, while PENDING, or if it had no figure then (it then follows the rate). */
  statedDue: string | null;
  /** The number of the SETTLED claim of the same person a correction (a negative amount) corrects; null on
   *  any other claim. */
  corrects: string | null;
}

/** Only OPEN, PENDING and SETTLED claims count toward what is claimed and due. */
export function counts(c: ClaimView): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING' || c.status === 'SETTLED';
}

/** Whether the claim counts in the live totals for a person held or not: while held, only SETTLED ones do. */
export function countsWhile(held: boolean): (c: ClaimView) => boolean {
  return held ? (c) => c.status === 'SETTLED' : counts;
}

/** The date (yyyy-mm-dd) that decides how a claim's live figures round: its own, or for a correction the date
 *  of the claim of the same person it corrects, found among that person's claims. */
export function roundingDate(
  c: Pick<ClaimView, 'date' | 'corrects'>,
